import pulp

# Initialize problem
prob = pulp.LpProblem("Service_Scheduling", pulp.LpMinimize)

# Teams, areas, services
TEAMS = [1, 2, 3]
AREAS = ['A', 'B', 'C', 'D']
SERVICES = ['H', 'D']

# Available hours for each team
AVAILABLE_HOURS = [8, 8, 8]

# Efficiency for each team and service
EFFICIENCY = {
    1: {'H': 2, 'D': 1},
    2: {'H': 1, 'D': 2},
    3: {'H': 1, 'D': 1}
}

# Demands for each area
DEMANDS = {
    'A': {'H': 3, 'D': 2},
    'B': {'H': 2, 'D': 3},
    'C': {'H': 4, 'D': 1},
    'D': {'H': 1, 'D': 4}
}

# Create variables
variables = {}
for team in TEAMS:
    for area in AREAS:
        for service in SERVICES:
            var_name = f"x_{team}_{area}_{service}"
            variables[(team, area, service)] = pulp.LpVariable(var_name, lowBound=0)

# Objective function: minimize total cost (sum of x_ijk * efficiency)
prob += pulp.lpSum(
    variables[(team, area, service)] * EFFICIENCY[team][service]
    for team in TEAMS
    for area in AREAS
    for service in SERVICES
)

# Constraints: meet the demand for each area and service
for area in AREAS:
    for service in SERVICES:
        prob += pulp.lpSum(
            variables[(team, area, service)] for team in TEAMS
        ) == DEMANDS[area][service]

# Constraints: team working hours not exceeded
for team in TEAMS:
    prob += pulp.lpSum(
        variables[(team, area, service)] * EFFICIENCY[team][service]
        for area in AREAS
        for service in SERVICES
    ) <= AVAILABLE_HOURS[team - 1]

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Print the answer
print(f"Answer: {round(pulp.value(prob.objective), 6)}")

import pulp

# Define the problem
prob = pulp.LpProblem("OptimizationProblem", pulp.LpMinimize)

# Define problem-specific parameters
COUNTRIES = [...]  # List of countries
CHANNELS = [...]   # List of channels
FEES = {...}       # Dictionary of fees: {country: {channel: value}}
TIMES = {...}      # Dictionary of times: {country: {channel: value}}
CONSTRAINTS = [...] # List of constraint specifications

# Create binary variables for each (country, channel) pair
variables = {}
for country in COUNTRIES:
    for channel in CHANNELS:
        variables[(country, channel)] = pulp.LpVariable(f"{country}_{channel}", cat='Binary')

# Add constraint: exactly one channel per country
for country in COUNTRIES:
    prob += pulp.lpSum([variables[(country, channel)] for channel in CHANNELS]) == 1

# Add specific constraints
for constraint in CONSTRAINTS:
    if constraint['type'] == 'fixed_channel':
        prob += variables[(constraint['country'], constraint['channel'])] == constraint['value']
    elif constraint['type'] == 'same_channel':
        for channel in CHANNELS:
            prob += variables[(constraint['country1'], channel)] == variables[(constraint['country2'], channel)]

# Objective function: minimize total cost (fee + time)
prob += pulp.lpSum([
    (FEES[country][channel] + TIMES[country][channel]) * variables[(country, channel)]
    for country in COUNTRIES for channel in CHANNELS
])

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Print result
print(f"Optimal solution: {round(pulp.value(prob.objective), 6)}")

import pulp

# Define problem parameters
COUNTRIES = ['US', 'China', 'Germany', 'Japan', 'India']
IP_TYPES = ['Patent', 'Trademark', 'Copyright']
VALUE_MATRIX = {
    'US': {'Patent': 1.5, 'Trademark': 2.0, 'Copyright': 2.5},
    'China': {'Patent': 2.0, 'Trademark': 1.5, 'Copyright': 2.0},
    'Germany': {'Patent': 2.5, 'Trademark': 2.0, 'Copyright': 1.5},
    'Japan': {'Patent': 2.0, 'Trademark': 2.5, 'Copyright': 2.0},
    'India': {'Patent': 1.5, 'Trademark': 2.0, 'Copyright': 2.5},
}
AVAILABLE_IPS = {'Patent': 100, 'Trademark': 80, 'Copyright': 70}
MAX_IPS_PER_COUNTRY = 20
MIN_IPS = {'US': 15, 'China': 15, 'Germany': 10, 'Japan': 10}

# Create optimization problem
prob = pulp.LpProblem("IP_Allocation", pulp.LpMaximize)

# Create variables for each country/IP type combination
variables = {}
for country in COUNTRIES:
    variables[country] = {}
    for ip in IP_TYPES:
        variables[country][ip] = pulp.LpVariable(f"{country}_{ip}", lowBound=0, cat='Continuous')

# Objective function: maximize total value
prob += pulp.lpSum([VALUE_MATRIX[country][ip] * variables[country][ip] 
                    for country in COUNTRIES for ip in IP_TYPES])

# Constraint 1: Total IP availability per type
for ip in IP_TYPES:
    prob += pulp.lpSum([variables[country][ip] for country in COUNTRIES]) <= AVAILABLE_IPS[ip]

# Constraint 2: Maximum IPs per country
for country in COUNTRIES:
    prob += pulp.lpSum([variables[country][ip] for ip in IP_TYPES]) <= MAX_IPS_PER_COUNTRY

# Constraint 3: Minimum IPs for specific countries
for country in MIN_IPS:
    prob += pulp.lpSum([variables[country][ip] for ip in IP_TYPES]) >= MIN_IPS[country]

# Solve and print result
prob.solve(pulp.PULP_CBC_CMD(msg=0))
print(f"Optimal value: {round(pulp.value(prob.objective), 6)}")

import pulp

# Define problem data
PLANT_COSTS = {'A': 5, 'B': 4, 'C': 3}
PLANT_CAPACITIES = {'A': 50, 'B': 60, 'C': 40}

WASTE_AMOUNTS = {1: 30, 2: 40, 3: 50, 4: 30}
TRANSPORT_COSTS = {
    1: {'A': 2, 'B': 3, 'C': 4},
    2: {'A': 3, 'B': 2, 'C': 3},
    3: {'A': 4, 'B': 3, 'C': 2},
    4: {'A': 3, 'B': 4, 'C': 1}
}

# Initialize PuLP problem
prob = pulp.LpProblem("Waste_Allocation", pulp.LpMinimize)

# Create decision variables
x = pulp.LpVariable.dicts("Allocation", [(i, j) for i in WASTE_AMOUNTS for j in PLANT_COSTS], lowBound=0, cat='Continuous')

# Objective function: total cost (transport + processing)
prob += pulp.lpSum(
    (TRANSPORT_COSTS[i][j] + PLANT_COSTS[j]) * x[(i, j)]
    for i in WASTE_AMOUNTS for j in PLANT_COSTS
)

# Constraints: waste generation points must be fully allocated
for i in WASTE_AMOUNTS:
    prob += pulp.lpSum(x[(i, j)] for j in PLANT_COSTS) == WASTE_AMOUNTS[i]

# Constraints: plant capacities must not be exceeded
for j in PLANT_CAPACITIES:
    prob += pulp.lpSum(x[(i, j)] for i in WASTE_AMOUNTS) <= PLANT_CAPACITIES[j]

# Solve the problem
prob.solve()

# Print the result
print(f"Answer: {round(pulp.value(prob.objective), 6)}")

import pulp

# Define problem parameters
NUM_TEACHERS = 5
NUM_TIME_SLOTS = 4
NUM_CLASSROOMS = 3
PREFERENCE_MATRIX = [
    [5, 4, 3, 2],
    [2, 5, 4, 3],
    [3, 2, 5, 4],
    [4, 3, 2, 5],
    [1, 2, 3, 4]
]

# Create optimization problem
prob = pulp.LpProblem("Maximize_Teacher_Preferences", pulp.LpMaximize)

# Create binary variables for teacher-classroom-time slot assignments
x = pulp.LpVariable.dicts(
    "assignment", 
    [(i, t, c) for i in range(NUM_TEACHERS) 
     for t in range(NUM_TIME_SLOTS) 
     for c in range(NUM_CLASSROOMS)], 
    cat='Binary'
)

# Objective function: maximize total preference score
prob += pulp.lpSum([
    PREFERENCE_MATRIX[i][t] * x[(i, t, c)] 
    for i in range(NUM_TEACHERS) 
    for t in range(NUM_TIME_SLOTS) 
    for c in range(NUM_CLASSROOMS)
])

# Constraint: Each teacher must be assigned exactly one class
for i in range(NUM_TEACHERS):
    prob += pulp.lpSum([
        x[(i, t, c)] 
        for t in range(NUM_TIME_SLOTS) 
        for c in range(NUM_CLASSROOMS)
    ]) == 1

# Constraint: Each classroom can have at most one class per time slot
for t in range(NUM_TIME_SLOTS):
    for c in range(NUM_CLASSROOMS):
        prob += pulp.lpSum([
            x[(i, t, c)] 
            for i in range(NUM_TEACHERS)
        ]) <= 1

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Print the optimal objective value
print(f"Maximum preference score: {round(pulp.value(prob.objective), 6)}")
